INSERT INTO tel_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TEL - Deep Learning','Telugu','Long Answer','Hard',5,'RNN క్రమ డేటాకు ఉపయోగకరం. వివరంగా వివరించండి.','','','','','RNN క్రమ డేటాకు ఉపయోగకరం. దీని ఉద్దేశ్యం, విధానం మరియు ఉపయోగాన్ని వివరించండి.','ఈ ప్రశ్న సంబంధిత అంశంలోని ప్రాథమిక భావనపై ఆధారపడి ఉంది.');
INSERT INTO tel_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TEL - Deep Learning','Telugu','Long Answer','Hard',5,'LSTM దీర్ఘ ఆధారాలను నేర్చుకోవడంలో సహాయపడుతుంది. వివరంగా వివరించండి.','','','','','LSTM దీర్ఘ ఆధారాలను నేర్చుకోవడంలో సహాయపడుతుంది. దీని ఉద్దేశ్యం, విధానం మరియు ఉపయోగాన్ని వివరించండి.','ఈ ప్రశ్న సంబంధిత అంశంలోని ప్రాథమిక భావనపై ఆధారపడి ఉంది.');
INSERT INTO tel_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TEL - Deep Learning','Telugu','Long Answer','Hard',5,'Dropout ఓవర్‌ఫిట్టింగ్ తగ్గించగలదు. వివరంగా వివరించండి.','','','','','Dropout ఓవర్‌ఫిట్టింగ్ తగ్గించగలదు. దీని ఉద్దేశ్యం, విధానం మరియు ఉపయోగాన్ని వివరించండి.','ఈ ప్రశ్న సంబంధిత అంశంలోని ప్రాథమిక భావనపై ఆధారపడి ఉంది.');
